const decoded = new Map<string, ReadonlyArray<number>>()

/**
 * The code point ranges (low, high, low, high, …) Go's `\p{name}` matches,
 * for a name already in Go's canonical form, or undefined for a name Go
 * rejects.
 */
export function goUnicodeRanges(
  canonical: string
): ReadonlyArray<number> | undefined {
  if (!Object.hasOwn(NAMES, canonical)) return undefined
  const table = NAMES[canonical]!
  const cached = decoded.get(table)
  if (cached) return cached
  const ranges =
    table === "!Cn" ? complement(rangesOf("Cn")) : rangesOf(table)
  decoded.set(table, ranges)
  return ranges
}

function rangesOf(table: string): Array<number> {
  const ranges: Array<number> = []
  let previous = -1
  const numbers = TABLES[table]!.split(",")
  for (let index = 0; index + 1 < numbers.length; index += 2) {
    const low = previous + 1 + Number.parseInt(numbers[index]!, 36)
    const high = low + Number.parseInt(numbers[index + 1]!, 36)
    ranges.push(low, high)
    previous = high
  }
  return ranges
}

/** The code points not in `ranges`, as ranges. */
export function complement(ranges: ReadonlyArray<number>): Array<number> {
  const out: Array<number> = []
  let next = 0
  for (let index = 0; index + 1 < ranges.length; index += 2) {
    if (ranges[index]! > next) out.push(next, ranges[index]! - 1)
    next = ranges[index + 1]! + 1
  }
  if (next <= 0x10_ff_ff) out.push(next, 0x10_ff_ff)
  return out
}
